import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL;

export const fetchResorts = async () => {
  try {
    const response = await axios.get(`${API_URL}/ski-resorts/resorts`);
    console.log("API response:", response.data);
    return response.data; // Ensure this is an array or contains an array
  } catch (error) {
    console.error(error);
    return { resorts: [] }; // Return an empty array in an object
  }
};

export const fetchResort = async (name) => {
  try {
    const response = await axios.get(`${API_URL}/ski-resorts/resort/${name}`);
    return response.data;
  } catch (error) {
    console.error(error);
    return null;
  }
};
